export function StorefrontFonts({ family }: { family: string }) {
  // This family is generated by next/font, never supplied by a visitor.
  // Keep this bootstrap independent of React hydration and its client bundle.
  const safeFamily = JSON.stringify(family).replace(/</g, "\\u003c");
  const script = `(() => {
    const family = ${safeFamily};
    const load = () => requestAnimationFrame(() => requestAnimationFrame(() => {
      Promise.all([
        document.fonts.load("400 1em " + family, "Tiệm sữa"),
        document.fonts.load("600 1em " + family, "Tiệm sữa")
      ]).then(() => document.documentElement.classList.add("sf-fonts-ready")).catch(() => {});
    }));
    if (document.readyState === "complete") load();
    else window.addEventListener("load", load, { once: true });
  })();`.replace(/\n\s*/g, "");
  return <script dangerouslySetInnerHTML={{ __html: script }} />;
}
